INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch12$PT128-S3-Q3$batch12$, 128, 3, 3, $batch12$Parallel$batch12$, $batch12$If Patricia eats a heavy, spicy meal tonight, she will get a bad case of heartburn later. If Patricia gets a bad case of heartburn later, she will be grouchy tomorrow morning. So if Patricia eats a heavy, spicy meal tonight, she will be grouchy tomorrow morning.$batch12$, $batch12$Which one of the following arguments is most similar in its logical features to the argument above?$batch12$, $batch12$D$batch12$, true, $batch12$Batch 12; question text from local bank.$batch12$ FROM lr_sections s WHERE s.preptest=128 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT128-S3-Q3$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$A$batch12$, $batch12$If Ruth plants only daffodils, the squirrels will eat the bulbs. If the squirrels eat the bulbs, then no flowers will bloom in Ruth's garden. Since no flowers are blooming in Ruth's garden, she must have planted only daffodils.$batch12$, $batch12$Bad Conclusion Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT128-S3-Q3$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$A$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$B$batch12$, $batch12$If Shawn starts gardening in early spring, he can plant tomatoes early. If Shawn can plant tomatoes early, he will have plenty of tomatoes for canning. But he does not have plenty of tomatoes for canning, so either he did not start gardening in early spring or he did not plant tomatoes early.$batch12$, $batch12$Bad Conclusion Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT128-S3-Q3$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$B$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$C$batch12$, $batch12$Maria plants either petunias or geraniums in her garden. If Maria plants petunias, she plants purple ones. If Maria plants geraniums, she plants red ones. Since both petunias and geraniums are flowers, Maria will have either purple or red flowers in her garden.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT128-S3-Q3$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$C$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$D$batch12$, $batch12$If Li plants old rose varieties, her garden will look beautiful. If Li's garden looks beautiful, Li's neighbors will be impressed. So if Li plants old rose varieties, her neighbors will be impressed.$batch12$, $batch12$Correct$batch12$, true FROM lr_questions q WHERE q.qid=$batch12$PT128-S3-Q3$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$D$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$E$batch12$, $batch12$If Bryan's fruit trees are to produce well, he must either prune them in the fall or fertilize them in the spring. Since Bryan wants his trees to produce well but forgot to prune them last fall, Bryan is sure to fertilize his trees this spring.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT128-S3-Q3$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$E$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT128-S3-Q3$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$If Patricia eats a heavy, spicy meal, Patricia will be grouchy tomorrow.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Spicy meal → heartburn. Heartburn → grouchy.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$A simple chain: A → B, B → C, so A → C.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Two linked conditionals and a conditional conclusion joining the ends.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT128-S3-Q3$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This affirms the end of the chain and concludes the start. Invalid, and not a conditional conclusion.$batch12$), ($batch12$B$batch12$, $batch12$This denies the end and concludes something about the start. Valid, but not a chained conditional.$batch12$), ($batch12$C$batch12$, $batch12$This works from an either/or.$batch12$), ($batch12$D$batch12$, $batch12$Old roses → beautiful garden → impressed neighbors. So old roses → impressed neighbors. Same chain.$batch12$), ($batch12$E$batch12$, $batch12$This uses a requirement with two options and rules one out.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT128-S3-Q3$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
